mapper.insert:
/* AiQuotaMapper.upsertUsage */
INSERT INTO TB_AI_TOKEN_USAGE (
    CMPNY_CD
  , USE_YM
  , INPUT_TOKENS
  , OUTPUT_TOKENS
  , CALL_CNT
) VALUES (
    #{cmpnyCd}
  , #{useYm}
  , #{inputTokens}
  , #{outputTokens}
  , 1
) AS NEW
ON DUPLICATE KEY UPDATE
    INPUT_TOKENS  = TB_AI_TOKEN_USAGE.INPUT_TOKENS + NEW.INPUT_TOKENS
  , OUTPUT_TOKENS = TB_AI_TOKEN_USAGE.OUTPUT_TOKENS + NEW.OUTPUT_TOKENS
  , CALL_CNT      = TB_AI_TOKEN_USAGE.CALL_CNT + 1
  , UPDATE_DATE   = NOW()
